function detectColumns(sql){const projection=(sql.replace(/--[^\n]*/g,'').match(/\bselect\s+([\s\S]+?)\s+from\b/i)||[])[1];if(!projection||projection.includes('*'))throw Error('Use explicit SELECT columns with aliases; SELECT * is not supported.');let parts=[],current='',depth=0;for(const ch of projection){if(ch==='(')depth++;if(ch===')')depth--;if(ch===','&&!depth){parts.push(current);current=''}else current+=ch}parts.push(current);const cols=parts.map(p=>(p.trim().match(/\bas\s+["`]?([\w]+)["`]?\s*$/i)||p.trim().match(/(?:^|\.)(\w+)\s*$/))?.[1]);if(cols.some(x=>!x)||new Set(cols).size!==cols.length)throw Error('Each output needs a unique column name or explicit AS alias.');return cols}
