function filterOps(type){return type==='Character'?['IN','NOT IN']:type==='Boolean'?['=','!=']:['=','!=','>','<','>=','<=','BETWEEN']}
function validateFilter(f,type){if(!filterOps(type).includes(f.op))throw Error('Comparison is not supported for this field type.');const parts=String(f.value).split(',').map(v=>v.trim());if(parts.some(v=>!v))throw Error('Enter a value for every filter condition.');if(['Integer','Float','Percentage','Number'].includes(type)){if(parts.length!==(f.op==='BETWEEN'?2:1)||parts.some(v=>!Number.isFinite(Number(v))))throw Error('Numeric filters require numeric values.');if(type==='Integer'&&parts.some(v=>!Number.isInteger(Number(v))))throw Error('Integer filters require whole numbers.');if(f.op==='BETWEEN'&&Number(parts[0])>Number(parts[1]))throw Error('BETWEEN requires the lower value first.');}}
function performanceFilters(c,i){return `<div class="section-gap"><div class="actions"><h3>Field Filters ${help('Conditions on selected performance keys. All calculations here use the structure evaluation period.')}</h3>${btn('+ Add condition','add-pfilter',i)}</div>${(c.filters||[]).length?select('Combine conditions',`components.${i}.filterJoin`,['AND','OR'],c.filterJoin||'AND'):''}${(c.filters||[]).map((f,j)=>`<div class="grid3 section-gap">${select('Field',`components.${i}.filters.${j}.key`,sharedKeys.filter(k=>[c.primary,...c.keys].includes(k.id)),f.key)}${select('Operator',`components.${i}.filters.${j}.op`,['=','!=','>','<','>=','<=','BETWEEN'],f.op)}${input('Value / range',`components.${i}.filters.${j}.value`,f.value)}${btn('Remove condition','remove-pfilter',`${i}|${j}`)}</div>`).join('')}</div>`}
function componentForm(c,i){const us=state.units.filter(u=>u.lob===draft.lob&&u.entity===draft.entity),u=state.units.find(u=>u.id===c.unit),attrs=u?.attributes.map(a=>a.name)||[];return `<section class="panel component" data-component="${i}"><div class="panel-head"><div class="component-title"><span class="number">${i+1}</span><h3>${esc(c.name)}</h3></div>${btn('Remove','remove-component',i)}</div><div class="panel-body"><div class="grid3">${input('Component name',`components.${i}.name`,c.name)}${input('Formula reference ID',`components.${i}.id`,c.id,'text','Use a unique ID with letters, numbers and underscores. Earlier component amounts are referenced with this ID.')} ${select('Calculation base',`components.${i}.basis`,['Fixed','Per Unit','Performance'],c.basis)}</div><div class="grid3 section-gap">${select('Operator',`components.${i}.effect`,['Add','Deduct'],c.effect)}${select('Value type',`components.${i}.valueType`,['Integer','Float','Percentage'],c.valueType)}${input('Default value',`components.${i}.defaultValue`,c.defaultValue,'number')}</div>${c.basis==='Per Unit'?`<div class="grid3 section-gap">${select('Registered unit',`components.${i}.unit`,us,c.unit)}${select('Value selection',`components.${i}.lookup`,['Flat','1D Lookup','2D Lookup'],c.lookup)}</div>${c.lookup!=='Flat'?`<div class="grid section-gap">${select('Lookup attribute 1',`components.${i}.attrs.0`,attrs,c.attrs[0])}${c.lookup==='2D Lookup'?select('Lookup attribute 2',`components.${i}.attrs.1`,attrs,c.attrs[1]||''):''}</div>`:''}<div class="grid3 section-gap">${select('Unit filter field',`components.${i}.unitFilterKey`,['',...attrs],c.unitFilterKey)}${select('Comparison',`components.${i}.unitFilterOp`,filterOps(u?.attributes.find(a=>a.name===c.unitFilterKey)?.type||'Character'),c.unitFilterOp)}${input('Filter values (comma-separated)',`components.${i}.unitFilterValue`,c.unitFilterValue)}</div>`:''}${c.basis==='Performance'?`<div class="grid section-gap">${select('Primary performance key',`components.${i}.primary`,sharedKeys,c.primary)}<div><label>Other available performance keys ${help('Selected keys can be used as formula inputs and additional slab conditions.')}</label><div class="field-list">${sharedKeys.filter(f=>f.id!==c.primary).map(f=>`<label><input type="checkbox" data-c-key="${i}|${f.id}" ${c.keys.includes(f.id)?'checked':''}>${esc(f.name)}</label>`).join('')}</div></div></div>${performanceFilters(c,i)}${ruleForm(c,i,false)}`:''}${c.basis!=='Performance'||!c.rules.length?`<label class="section-gap">Formula ${help('Use value, selected numeric fields, earlier component IDs, running_payout, + − * /, MIN and MAX.')}<input data-k="components.${i}.formula" value="${esc(c.formula)}"></label>`:''}<div class="formula">${esc(c.effect)}: ${c.basis==='Per Unit'?'SUM for qualifying units of ':''}${esc(c.rules.length?'SUM of applicable slab formulas':c.formula)}</div>${c.basis==='Per Unit'?`<p class="quiet">Available attributes: ${attrs.map(esc).join(', ')||'Register a unit first.'}</p>`:''}</div></section>`}
function ruleForm(c,i,manager){return `<div class="section-gap"><div class="actions"><h3>Performance slab rules</h3>${btn('+ Add slab rule','add-rule',i)}</div>${c.rules.map((r,j)=>`<div class="rule"><div class="rule-head"><strong>Slab ${j+1} · ${esc(displayKey(c.primary))}</strong>${btn('Remove','remove-rule',`${i}|${j}`)}</div><div class="grid3">${input('Slab minimum',`components.${i}.rules.${j}.min`,r.min,'number')}${input('Slab maximum',`components.${i}.rules.${j}.max`,r.max,'number')}${input('Value',`components.${i}.rules.${j}.value`,r.value,'number')}</div>${true?`<div class="grid3 section-gap">${select('Applicable when',`components.${i}.rules.${j}.when`,['Slab not achieved','Slab achieved','Both'],r.when)}${select('Not applicable if',`components.${i}.rules.${j}.exclude`,['NA','Any subsequent slab achieved'],r.exclude)}${select('Value type',`components.${i}.rules.${j}.valueType`,['Integer','Float','Percentage'],r.valueType||'Float')}</div><div class="grid section-gap">${select('Additional target key',`components.${i}.rules.${j}.secondary`,[{id:'',name:'None'},...sharedKeys.filter(f=>c.keys.includes(f.id)&&f.id!==c.primary)],r.secondary||'')}${input('Additional target ≥',`components.${i}.rules.${j}.secondaryMax`,r.secondaryMax||0,'number')}</div><label class="section-gap">Formula<input data-k="components.${i}.rules.${j}.formula" value="${esc(r.formula)}"></label>`:`<div class="quiet section-gap">${esc(r.when)} · Exclusion: ${esc(r.exclude)}${r.secondary?` · ${esc(displayKey(r.secondary))} ≥ ${r.secondaryMax}`:''}</div><code class="formula">${esc(r.formula)}</code>`}</div>`).join('')}${!c.rules.length?'<p class="quiet">No slabs. Calculate using the formula and registered fields directly.</p>':''}</div>`}
function openTemplate(id){editorType='template';draft=clone(template(id)||{id:uid(),name:'',structure:'',components:[]});templateForm()}
function loadTemplateStructure(id){const s=structure(id);draft.structure=id;draft.components=s.components.map(c=>({...clone(c),rates:ratesFor(c)}));templateForm()}
function templateForm(){const s=structure(draft.structure);modal(draft.name||'Create rate template',`<div class="grid">${input('Template name','name',draft.name)}${select('Payout structure','structure',[{id:'',name:'Select a live structure'},...current(state.structures).filter(s=>s.status==='Live')],draft.structure)}</div>${s?`<div class="notice">${esc(s.lob)} / ${esc(s.entity)} · User Type: ${esc(s.userType)} · Evaluation: <strong>${s.period}</strong> · Ongoing<br>Fields, calculation bases and evaluation period come from Admin. Set template rates and performance rules below. Slab formulas can also use slab_min, slab_max, slab_width and slab_quantity (capped progress inside the band).</div>${draft.components.map((c,i)=>`<section class="panel"><div class="panel-head"><h3>${esc(c.name)}</h3><span class="tag">${c.basis} · ${c.effect}</span></div><div class="panel-body">${c.basis==='Performance'?performanceFilters(c,i):''}${c.lookup!=='Flat'&&c.basis==='Per Unit'?`${table([...c.attrs.slice(0,c.lookup==='2D Lookup'?2:1).map(esc),'Value'],c.rates.map((r,j)=>row([...r.keys.map(esc),`<input type="number" step="any" data-k="components.${i}.rates.${j}.value" value="${r.value}" aria-label="${esc(r.keys.join(' '))} rate">`])))}${!c.rates.length?'<div class="notice warn">No sample attribute values available. Add lookup rows before saving.</div>':''}${btn('+ Add lookup row','add-rate',i)}<div class="section-gap"></div><p class="quiet">${c.skip?`Only units after the first ${c.skip}, ordered by date/time then Unit ID.`:'All qualifying units.'}</p>`:c.basis==='Performance'?`${ruleForm(c,i,true)}${!c.rules.length?input(`Value (${c.valueType})`,`components.${i}.defaultValue`,c.defaultValue,'number'):''}`:input(`Value (${c.valueType})`,`components.${i}.defaultValue`,c.defaultValue,'number')}<code class="formula">${esc(c.effect)} · ${esc(c.rules.length?'Applicable slab formulas':c.formula)}</code></div></section>`).join('')}`:''}`,btn('Save template','save-template','',true))}
// Small arithmetic parser: no eval, assignments or JavaScript execution.
function formulaEval(source,vars){const text=String(source),tokens=text.match(/\d*\.\d+|\d+\.?\d*|[A-Za-z_]\w*|[()+*/,-]/g)||[];if(tokens.join('')!==text.replace(/\s/g,''))throw Error('Unsupported formula character.');let p=0;function atom(){const t=tokens[p++];if(t==='-')return -atom();if(t==='+')return atom();if(t==='('){const n=expr();if(tokens[p++]!==')')throw Error('Missing closing parenthesis.');return n}if(/^\d|^\./.test(t||''))return Number(t);if(t==='MIN'||t==='MAX'){if(tokens[p++]!=='(')throw Error('Expected function parentheses.');const a=expr();if(tokens[p++]!==',')throw Error('MIN / MAX require two inputs.');const b=expr();if(tokens[p++]!==')')throw Error('Missing closing parenthesis.');return t==='MIN'?Math.min(a,b):Math.max(a,b)}if(Object.hasOwn(vars,t)){const n=Number(vars[t]);if(vars[t]==null||!Number.isFinite(n))throw Error(sharedKeys.some(k=>k.formulaKey===t)?`No sample data for registered key: ${t}. The query is registered, but live SQL execution is not connected.`:`Missing numeric input: ${t}`);return n}throw Error(`Unknown formula input: ${t||'(empty)'}`)}function term(){let n=atom();while(['*','/'].includes(tokens[p])){const op=tokens[p++],b=atom();if(op==='/'&&b===0)throw Error('Division by zero.');n=op==='*'?n*b:n/b}return n}function expr(){let n=term();while(['+','-'].includes(tokens[p])){const op=tokens[p++],b=term();n=op==='+'?n+b:n-b}return n}const n=expr();if(p!==tokens.length||!Number.isFinite(n))throw Error('Invalid formula.');return n}
function compare(v,op,raw){const a=String(raw).split(',').map(x=>x.trim());if(v==null)return false;if(op==='IN')return a.includes(String(v));if(op==='NOT IN')return !a.includes(String(v));if(op==='=')return typeof v==='number'?v===Number(raw):String(v)===String(raw);if(op==='!=')return typeof v==='number'?v!==Number(raw):String(v)!==String(raw);const n=Number(v),x=Number(a[0]);return ({'>':()=>n>x,'<':()=>n<x,'>=':()=>n>=x,'<=':()=>n<=x,'BETWEEN':()=>n>=x&&n<=Number(a[1])})[op]?.()||false}
const scaled=(v,type)=>type==='Percentage'?v/100:v;
function calculate(t,u){const s=structure(t.structure);if(!s)throw Error('Structure not found.');if(u.lob!==s.lob||u.entity!==s.entity||(s.userType!=='All'&&s.userType!==u.type))throw Error('Entity does not match this structure.');if(s.period==='Weekly')throw Error('Weekly structure saved; no full-week sample dataset is connected.');const needsAttendance=t.components.some(c=>[c.primary,...c.keys].some(k=>['attendance_days','absent_days'].includes(k)));if(needsAttendance&&((u.id==='RDR-1043'&&s.period!=='Monthly')||(u.id!=='RDR-1043'&&s.period!=='Daily')))throw Error('No attendance sample is available for this entity and evaluation period.');const all=sampleUnits.filter(x=>x.rider_id===u.id&&x.status==='Delivered').sort((a,b)=>a.delivered_at.localeCompare(b.delivered_at)||a.shipment_id.localeCompare(b.shipment_id));const metrics={shipment_count:all.length,attendance_days:u.attendance_days,absent_days:u.absent_days,total_km:u.total_km,closure:u.closure};let total=0,refs={},lines=[],unitOutputs={};for(const c of t.components){let amount=0,detail='',scope={...formulaScope(c.keys||[],metrics),...refs,running_payout:total,__resolveOutput:t.__resolveOutput};if(c.basis==='Per Unit'){const unit=state.units.find(x=>x.id===c.unit);if(!unit?.sample)throw Error(`${c.name}: unit query has no connected sample data.`);unitOutputs[c.id]=Object.fromEntries(all.map(r=>[r[unit.unitId],0]));const candidates=all.filter(r=>!c.unitFilterKey||compare(r[c.unitFilterKey],c.unitFilterOp,c.unitFilterValue));const paid=candidates;for(const record of paid){let value=c.defaultValue;if(c.lookup!=='Flat'){const attrs=c.attrs.slice(0,c.lookup==='2D Lookup'?2:1),r=c.rates?.find(r=>lookupMatches(c,r,record));if(!r)throw Error(`${c.name}: missing lookup rate for ${record.shipment_id}.`);value=r.value}const unitAmount=formulaEval(c.formula,{...scope,...record,value:scaled(value,c.valueType),__resolveOutput:token=>{const local=t.components.find(p=>p.basis==='Per Unit'&&typeof unitComponentKey==='function'&&token===unitComponentKey(p));if(local)return readUnitOutput(unitOutputs[local.id],record[unit.unitId]);if(t.__resolveOutput)return t.__resolveOutput(token,{unit:c.unit,id:record[unit.unitId]});throw Error('Unknown unit output: '+token)}});unitOutputs[c.id][record[unit.unitId]]=unitAmount;amount+=unitAmount}detail=`${paid.length} paid of ${candidates.length} qualifying units`}
else if(c.basis==='Performance'){const values=Object.fromEntries([c.primary,...c.keys].map(k=>[k,metrics[k]]));const conditionResults=(c.filters||[]).map(f=>compare(metrics[f.key],f.op,f.value));const eligible=!conditionResults.length||(c.filterJoin==='OR'?conditionResults.some(Boolean):conditionResults.every(Boolean));if(!eligible){refs[c.id]=0;lines.push({name:c.name,effect:c.effect,amount:0,detail:'Field filters not met'});continue}if(c.rules.length){const n=metrics[c.primary];if(n==null)throw Error(`No sample value for ${c.primary}`);let used=0;const achieved=r=>n>=r.max&&(!r.secondary||metrics[r.secondary]>=r.secondaryMax)&&Object.entries(r.targets||{}).every(([k,v])=>v===''||v==null||Number.isNaN(v)||metrics[k]>=v);for(const r of c.rules){const entered=n>=r.min,done=achieved(r);const applicable=r.when==='Slab achieved'?done:r.when==='Slab not achieved'?entered&&!done:entered;const excluded=r.exclude!=='NA'&&c.rules.some(next=>next.max>r.max&&achieved(next));if(applicable&&!excluded){amount+=formulaEval(r.formula,{...scope,...values,value:scaled(r.value,r.valueType||c.valueType),slab_min:r.min,slab_max:r.max,slab_width:r.max-r.min,slab_quantity:Math.max(0,Math.min(n,r.max)-r.min)});used++}}detail=`${displayKey(c.primary)}: ${n}; ${used} applicable rule(s)`}else {amount=formulaEval(c.formula,{...scope,...values,value:scaled(c.defaultValue,c.valueType)});detail=[c.primary,...c.keys].filter((x,i,a)=>a.indexOf(x)===i).map(k=>`${displayKey(k)}: ${metrics[k]??'unavailable'}`).join(' · ')}}
else {const results=(c.filters||[]).map(f=>{if(metrics[f.key]==null)throw Error('No sample value for '+displayKey(f.key));return compare(metrics[f.key],f.op,f.value)});const eligible=!results.length||(c.filterJoin==='OR'?results.some(Boolean):results.every(Boolean));amount=eligible?formulaEval(c.formula,{...scope,value:scaled(c.defaultValue,c.valueType)}):0;detail=eligible?'Formula: '+c.formula+' · Value: '+c.defaultValue+' · '+(c.keys||[]).map(k=>displayKey(k)+': '+(metrics[k]??'unavailable')).join(' · '):'Conditions not met';}if(amount<0)throw Error(`${c.name}: negative result. Choose Add or Deduct; formula amount must be non-negative.`);amount=Math.round(amount*100)/100;refs[c.id]=amount;refs[componentOutputKey(c)]=amount;if(typeof periodComponentKey==='function')refs[periodComponentKey(s,c)]=amount;total+=c.effect==='Deduct'?-amount:amount;lines.push({name:c.name,effect:c.effect,amount,detail})}return {total:Math.round(total*100)/100,lines,metrics,unitOutputs}}
function preview(id,userId){editorType='preview';const t=template(id),s=structure(t.structure),us=users.filter(u=>u.lob===s.lob&&u.entity===s.entity&&(s.userType==='All'||s.userType===u.type)),u=us.find(x=>x.id===userId)||us[0];let result='',error='';try{if(!u)throw Error('No sample entity matches this structure.');const r=calculate(t,u);result=table(['Component','Calculation inputs','Operator','Amount'],r.lines.map(l=>row([esc(l.name),esc(l.detail),l.effect,money(l.amount)])))+`<div class="panel-body"><span class="quiet">NET PAYOUT · ${s.period.toUpperCase()}</span><div class="result-total">${money(r.total)}</div></div>`}catch(e){error=`<div class="notice error">${esc(e.message)}</div>`}modal('Calculation preview',`<div class="grid"><div><h2>${esc(t.name)}</h2><p class="quiet">${esc(s.name)} · ${s.period}</p></div><label>Sample entity<select id="preview-user" data-template="${t.id}">${opts(us.map(u=>({id:u.id,name:u.name+' · '+u.id})),u?.id)}</select></label></div><div class="notice">Sample snapshot: ${s.period==='Monthly'?'October 2026 attendance':'13 Oct 2026'}. This calculation uses fixture records, not live SQL results.</div>${error}${result}`)}
function openAssignment(kind,id){editorType='assignment';draft=clone(state.assignments.find(a=>a.id===id)||{id:uid(),kind,target:'',template:''});assignmentForm()}
function assignmentForm(){const t=template(draft.template),s=t&&structure(t.structure);const targets=draft.kind==='User'?entityUsers().filter(u=>!s||s.userType==='All'||u.type===s.userType).map(u=>({id:u.id,name:u.name+' · '+u.type})): [...new Set(entityUsers().filter(u=>!s||s.userType==='All'||u.type===s.userType).map(u=>u.center))];modal(`Assign to ${draft.kind.toLowerCase()}`,`<div class="grid">${select('Template','template',[{id:'',name:'Select template'},...currentTemplates().filter(t=>structure(t.structure).status==='Live')],draft.template)}${select(draft.kind,'target',[{id:'',name:'Select '+draft.kind.toLowerCase()},...targets],draft.target)}</div>${s?`<div class="notice">${esc(s.name)} · ${s.period} · User Type: ${esc(s.userType)}<br>Only matching entities receive this template.</div>`:''}`,btn('Save assignment','save-assignment','',true))}
function assign(a){const t=template(a.template),s=t&&structure(t.structure);if(!a.target||!t||s.status!=='Live')throw Error('Select a target and a template from a live structure.');const affected=users.filter(u=>u.lob===s.lob&&u.entity===s.entity&&(s.userType==='All'||u.type===s.userType)&&(a.kind==='User'?u.id===a.target:u.center===a.target));if(!affected.length)throw Error('No eligible sample entities match this assignment.');const clash=state.assignments.find(x=>x.id!==a.id&&x.kind!==a.kind&&template(x.template)?.structure===s.id&&affected.some(u=>x.kind==='User'?x.target===u.id:x.target===u.center));if(clash)throw Error('This structure already has an overlapping direct/center assignment. Remove it before assigning.');state.assignments=state.assignments.filter(x=>x.id!==a.id&&!(x.kind===a.kind&&x.target===a.target&&template(x.template)?.structure===s.id));state.assignments.push(clone(a))}
function openTrigger(id){editorType='trigger';draft=clone(state.triggers.find(x=>x.id===id)||{id:uid(),name:'',field:'center',op:'=',value:'',userType:'All',action:'Assign template',template:'',enabled:false});triggerForm()}
function triggerForm(){modal('Trigger logic',`<div class="grid">${input('Rule name','name',draft.name)}${select('Template','template',[{id:'',name:'Select template'},...currentTemplates()],draft.template)}</div><section class="panel"><div class="panel-head"><h3>If this happens</h3></div><div class="panel-body grid3">${select('Entity attribute','field',['center','type','id'],draft.field)}${select('Comparison','op',['=','!=','IN','NOT IN'],draft.op)}${input('Value(s)','value',draft.value)}</div></section><div class="grid">${select('And User Type','userType',['All','OR','LMA','OFR','Agent'],draft.userType)}${select('Then do this','action',['Assign template','Remove template'],draft.action)}</div><label class="section-gap"><input type="checkbox" data-k="enabled" ${draft.enabled?'checked':''}>Enabled for manual simulation</label><div class="notice">Match current sample entity attributes, then explicitly apply the action. No background trigger execution.</div>`,btn('Save trigger','save-trigger','',true))}
function testTrigger(id){const t=state.triggers.find(x=>x.id===id),tpl=template(t.template),s=structure(tpl.structure),matches=users.filter(u=>u.lob===s.lob&&u.entity===s.entity&&(s.userType==='All'||s.userType===u.type)&&(t.userType==='All'||u.type===t.userType)&&compare(u[t.field],t.op,t.value));editorType='trigger-test';draft={triggerId:id};modal('Test trigger',`<h2>${esc(t.name)}</h2><div class="notice">${matches.length} sample entities match. Action: ${esc(t.action)} → ${esc(tpl.name)}.</div>${table(['Entity','Center','Type'],matches.map(u=>row([esc(u.name)+' · '+u.id,u.center,u.type])))}${!t.enabled?'<div class="notice warn">This rule is disabled. Enable it before applying.</div>':''}`,t.enabled&&matches.length?btn('Apply to matching sample users','apply-trigger',id,true):'')}
function applyTrigger(id){const t=state.triggers.find(x=>x.id===id),tpl=template(t.template),s=structure(tpl.structure),matches=users.filter(u=>u.lob===s.lob&&u.entity===s.entity&&(s.userType==='All'||s.userType===u.type)&&(t.userType==='All'||u.type===t.userType)&&compare(u[t.field],t.op,t.value));const before=clone(state.assignments);try{for(const u of matches){if(t.action==='Assign template')assign({id:uid(),kind:'User',target:u.id,template:t.template});else state.assignments=state.assignments.filter(a=>!(a.kind==='User'&&a.target===u.id&&a.template===t.template))}}catch(e){state.assignments=before;throw e}save();$('#editor').close();render();notify('Applied to matching sample user assignments.')}
function validateStructure(s){if(!s.name.trim()||!s.components.length)throw Error('Enter a structure name and at least one component.');const ids=new Set();let refs={running_payout:1000,value:1,...structureOutputPlaceholders(s)};for(const c of s.components){if(!c.name.trim()||!/^\w+$/.test(c.id)||/^\d/.test(c.id)||ids.has(c.id)||['value','running_payout','MIN','MAX','MOD','IF','AND','OR','NOT','TRUE','FALSE','slab_min','slab_max','slab_width','slab_quantity',...sharedKeys.flatMap(k=>[k.id,k.formulaKey])].includes(c.id))throw Error('Component IDs must be unique identifiers and must not shadow formula inputs.');ids.add(c.id);if(!Number.isFinite(c.defaultValue)||c.defaultValue<0)throw Error('Default values must be non-negative.');if(c.valueType==='Integer'&&!Number.isInteger(c.defaultValue))throw Error('Integer values must be whole numbers.');let vars={...refs};(c.keys||[]).forEach(k=>{vars[k]=1;vars[formulaKey(k)]=1});if(c.basis==='Per Unit'){const u=state.units.find(u=>u.id===c.unit);if(!u||u.lob!==s.lob||u.entity!==s.entity)throw Error('Select a registered unit for the same entity context.');const attrs=c.attrs.slice(0,c.lookup==='2D Lookup'?2:1);if(c.lookup!=='Flat'&&(attrs.length!==(c.lookup==='2D Lookup'?2:1)||new Set(attrs).size!==attrs.length||attrs.some(x=>!u.attributes.some(a=>a.name===x))))throw Error('Select distinct registered lookup attributes.');if(c.unitFilterKey&&c.unitFilterOp==='BETWEEN'&&(c.unitFilterValue.split(',').length!==2||c.unitFilterValue.split(',').some(v=>!v.trim()||!Number.isFinite(Number(v)))||Number(c.unitFilterValue.split(',')[0])>Number(c.unitFilterValue.split(',')[1])))throw Error('BETWEEN requires two ordered numeric values separated by a comma.');if(c.unitFilterKey){const attr=u.attributes.find(a=>a.name===c.unitFilterKey);if(!attr)throw Error('Choose a registered unit filter attribute.');validateFilter({op:c.unitFilterOp,value:c.unitFilterValue},attr.type);}u.attributes.filter(a=>['Integer','Float','Percentage'].includes(a.type)).forEach(a=>vars[a.name]=1)}if(c.basis==='Performance'){if(!sharedKeys.some(k=>k.id===c.primary))throw Error('Select a registered primary key.');[c.primary,...c.keys].forEach(k=>vars[k]=1)}for(const f of c.filters||[]){validateFilter(f,sharedKeys.find(k=>k.id===f.key)?.type||'Float');if(![c.primary,...c.keys].includes(f.key)||!String(f.value).trim())throw Error('Field filters must use selected keys and have values.');if(f.op==='BETWEEN'&&(String(f.value).split(',').length!==2||String(f.value).split(',').some(v=>!v.trim()||!Number.isFinite(Number(v)))||Number(String(f.value).split(',')[0])>Number(String(f.value).split(',')[1])))throw Error('Field BETWEEN requires two ordered numeric values.');}if(c.rules.length&&c.basis==='Performance'){for(const r of c.rules){if(!Number.isFinite(r.min)||!Number.isFinite(r.max)||r.min<0||r.max<=r.min||!Number.isFinite(r.value)||r.value<0)throw Error('Slab bounds must be non-negative with maximum greater than minimum.');if(r.valueType==='Integer'&&!Number.isInteger(r.value))throw Error('Integer slab values must be whole numbers.');if(r.secondary&&(!Number.isFinite(r.secondaryMax)||r.secondaryMax<0))throw Error('Additional slab targets must be non-negative numbers.');if(r.secondary&&!c.keys.includes(r.secondary))throw Error('Additional slab target must be an available performance key.');validateFormula(r.formula,{...vars,slab_min:r.min,slab_max:r.max,slab_width:r.max-r.min,slab_quantity:1})}}else validateFormula(c.formula,vars);refs[c.id]=1000;refs[componentOutputKey(c)]=1000;if(typeof periodComponentKey==='function')refs[periodComponentKey(s,c)]=1000;if(typeof unitComponentKey==='function'&&c.basis==='Per Unit')refs[unitComponentKey(c)]=1000}}
function setPath(obj,path,v){const keys=path.split('.');let x=obj;keys.slice(0,-1).forEach(k=>{if(x[k]==null)x[k]={};x=x[k]});x[keys.at(-1)]=v}
function saveRecord(list,obj){const i=list.findIndex(x=>x.id===obj.id);if(i<0)list.push(clone(obj));else list[i]=clone(obj)}
function finish(msg){save();$('#editor').close();render();notify(msg)}
document.addEventListener('input',e=>{const k=e.target.dataset.k;if(!k||!draft)return;setPath(draft,k,e.target.dataset.rangeMax!==undefined?parseRangeMax(e.target.value):e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?(e.target.value.trim()===''?NaN:Number(e.target.value)):e.target.value);if(editorType==='unit'&&k==='sql')draft.queryChanged=true});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='role'){role=el.value;render();return}if(el.id==='lob'){lob=el.value;entity=mappings.find(x=>x.lob===lob).entity;render();return}if(el.id==='entity'){entity=el.value;render();return}if(el.id==='preview-user'){preview(el.dataset.template,el.value);return}if(el.dataset.k&&draft){setPath(draft,el.dataset.k,el.dataset.rangeMax!==undefined?parseRangeMax(el.value):el.type==='checkbox'?el.checked:el.type==='number'?(el.value.trim()===''?NaN:Number(el.value)):el.value);const k=el.dataset.k;if(editorType==='template'&&k==='structure'){if(el.value)loadTemplateStructure(el.value);else{draft.components=[];templateForm()}return}if(editorType==='assignment'&&k==='template'){draft.target='';assignmentForm();return}if(editorType==='unit'&&['unitId','entityId','date'].includes(k)){draft.attributes=draft.attributes.filter(a=>![draft.unitId,draft.entityId,draft.date].includes(a.name));unitForm();return}if(editorType==='structure'&&/\.(basis|unit|lookup|primary|unitFilterKey)$/.test(k)){const c=draft.components[Number(k.split('.')[1])];if(k.endsWith('unitFilterKey')){const type=state.units.find(u=>u.id===c.unit)?.attributes.find(a=>a.name===c.unitFilterKey)?.type||'Character';c.unitFilterOp=filterOps(type)[0];c.unitFilterValue='';}if(k.endsWith('primary')&&!c.keys.includes(c.primary))c.keys.push(c.primary);if(k.endsWith('lookup')&&c.lookup==='2D Lookup'&&!c.attrs[1])c.attrs[1]=state.units.find(u=>u.id===c.unit)?.attributes.find(a=>a.name!==c.attrs[0])?.name||'';if(k.endsWith('basis')){c.rules=[];c.formula='value';if(c.basis==='Per Unit')c.unit=state.units.find(u=>u.lob===draft.lob&&u.entity===draft.entity)?.id||'';}structureForm();return}}if(el.dataset.attr){if(el.checked)draft.attributes.push({name:el.dataset.attr,type:'Character'});else draft.attributes=draft.attributes.filter(a=>a.name!==el.dataset.attr)}if(el.dataset.attrType){const a=draft.attributes.find(a=>a.name===el.dataset.attrType);if(a)a.type=el.value}if(el.dataset.cKey){const [i,key]=el.dataset.cKey.split('|'),c=draft.components[i];c.keys=el.checked?[...new Set([...c.keys,key])]:c.keys.filter(x=>x!==key)}});
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){view=nav.dataset.view;render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{switch(a){case 'close':$('#editor').close();break;case 'new-unit':openUnit();break;case 'edit-unit':openUnit(id);break;case 'detect-unit':{draft.columns=detectColumns(draft.sql);draft.unitId=draft.columns.includes(draft.unitId)?draft.unitId:draft.columns[0];draft.entityId=draft.columns.includes(draft.entityId)?draft.entityId:draft.columns[1]||'';draft.date=draft.columns.includes(draft.date)?draft.date:draft.columns.find(x=>/date|_at|time/.test(x))||'';draft.attributes=draft.columns.filter(x=>![draft.unitId,draft.entityId,draft.date].includes(x)).map(name=>draft.attributes.find(a=>a.name===name)||{name,type:/kg|km/.test(name)?'Float':'Character'});unitForm();break}case 'save-unit':if(!draft.name.trim()||!draft.columns.length||new Set([draft.unitId,draft.entityId,draft.date]).size!==3||[draft.unitId,draft.entityId,draft.date].some(x=>!draft.columns.includes(x)))throw Error('Enter a name, detect columns, and choose three distinct ID/date mappings.');if(JSON.stringify(detectColumns(draft.sql))!==JSON.stringify(draft.columns))throw Error('Query columns changed. Detect columns again.');if(draft.queryChanged||draft.unitId!=='shipment_id'||draft.entityId!=='rider_id'||draft.date!=='delivered_at'){draft.sample=false;delete draft.queryChanged}saveRecord(state.units,draft);finish('Unit saved.');break;
case 'duplicate-structure':editorType='structure';draft=clone(structure(id));draft.id=uid();draft.name+=' · Copy';draft.status='Draft';structureForm();break;case 'add-pfilter':{const c=draft.components[id];c.filters||=[];c.filters.push({key:c.primary,op:'>=',value:'0'});editorType==='template'?templateForm():structureForm();break}case 'remove-pfilter':{const [i,j]=id.split('|');draft.components[i].filters.splice(Number(j),1);editorType==='template'?templateForm():structureForm();break}case 'new-structure':openStructure();break;case 'edit-structure':openStructure(id);break;case 'add-component':draft.components.push(comp('component_'+(draft.components.length+1),'New component'));structureForm();break;case 'remove-component':draft.components.splice(Number(id),1);structureForm();break;case 'add-rule':{const c=draft.components[id],last=c.rules.at(-1)?.max||0;c.rules.push(editorType==='template'?{...clone(structure(draft.structure)?.components.find(x=>x.id===c.id)?.rules[0]||slab(0,50,0)),min:last,max:last+50,value:0}:slab(last,last+50,0));editorType==='template'?templateForm():structureForm();break}case 'remove-rule':{const [i,j]=id.split('|');draft.components[i].rules.splice(Number(j),1);editorType==='template'?templateForm():structureForm();break}case 'save-structure':validateStructure(draft);if(state.templates.some(t=>t.structure===draft.id)){const old=structure(draft.id);const shape=x=>x.components.map(c=>[c.id,c.basis,c.unit,c.lookup,c.attrs]);if(JSON.stringify(shape(old))!==JSON.stringify(shape(draft))||old.period!==draft.period||old.userType!==draft.userType)throw Error('Duplicate this structure to change its units, components or period. Formulas can be updated here.');syncTemplateDefinitions(draft);}saveRecord(state.structures,draft);finish('Payout structure saved.');break;
case 'new-template':openTemplate();break;case 'edit-template':openTemplate(id);break;case 'add-rate':{const c=draft.components[id];editorType='rate';draft.rateComponent=Number(id);modal('Add lookup row',`<div class="grid">${c.attrs.slice(0,c.lookup==='2D Lookup'?2:1).map((a,i)=>`<label>${esc(a)}<input id="rate-key-${i}" required></label>`).join('')}<label>Value<input id="rate-value" type="number" min="0" step="any" value="0"></label></div>`,btn('Add row','save-rate','',true));break}case 'save-rate':{const c=draft.components[draft.rateComponent],keys=c.attrs.slice(0,c.lookup==='2D Lookup'?2:1).map((_,i)=>$('#rate-key-'+i).value.trim());if(keys.some(x=>!x)||c.rates.some(r=>JSON.stringify(r.keys)===JSON.stringify(keys)))throw Error('Enter a unique, non-empty lookup combination.');c.rates.push({keys,value:Number($('#rate-value').value)});editorType='template';delete draft.rateComponent;templateForm();break}case 'save-template':if(!draft.name.trim()||!draft.structure||!draft.components.length)throw Error('Enter a template name and choose a structure.');if(state.templates.some(t=>t.id!==draft.id&&t.name.toLowerCase()===draft.name.trim().toLowerCase()))throw Error('Use a unique template name.');for(const c of draft.components){const values=c.rules.length?c.rules.map(r=>r.value):c.lookup!=='Flat'&&c.basis==='Per Unit'?(c.rates||[]).map(r=>r.value):[c.defaultValue];if(!values.length||values.some(v=>!Number.isFinite(v)||v<0)||(c.valueType==='Integer'&&values.some(v=>!Number.isInteger(v))))throw Error('Enter valid non-negative values for all rates; Integer requires whole numbers.');}validateStructure({...structure(draft.structure),components:draft.components});saveRecord(state.templates,draft);finish('Rate template saved.');break;
case 'preview':{const [t,u]=id.split('|');preview(t,u);break}case 'new-assignment':openAssignment(id);break;case 'edit-assignment':{const a=state.assignments.find(a=>a.id===id);openAssignment(a.kind,id);break}case 'save-assignment':assign(draft);finish('Assignment saved for sample entities.');break;case 'remove-assignment':state.assignments=state.assignments.filter(a=>a.id!==id);save();render();notify('Assignment removed.');break;
case 'new-trigger':openTrigger();break;case 'edit-trigger':openTrigger(id);break;case 'save-trigger':if(!draft.name.trim()||!draft.value.trim()||!template(draft.template))throw Error('Enter a name, condition value and template.');saveRecord(state.triggers,draft);finish('Trigger saved for manual simulation.');break;case 'test-trigger':testTrigger(id);break;case 'apply-trigger':applyTrigger(id);break;}}
catch(e){if($('#editor').open)fail(e.message);else notify(e.message)}});
render();save();
window.PayoutTest={formulaEval,calculate,compare,detectColumns,state,users,validateStructure};
